import type {MedusaRequest,MedusaResponse} from '@medusajs/framework/http'
import {ContainerRegistrationKeys} from '@medusajs/framework/utils'
const actor=(r:MedusaRequest)=>(r as any).auth_context?.actor_id||(r as any).auth_context?.auth_identity_id
async function seller(req:MedusaRequest,a:string){const q=req.scope.resolve(ContainerRegistrationKeys.QUERY) as any;try{const {data}=await q.graph({entity:'seller_member',fields:['seller.id','seller.name','seller.email'],filters:{member_id:a},pagination:{take:1}});return data?.[0]?.seller||null}catch{return null}}
export async function GET(req:MedusaRequest,res:MedusaResponse){const a=actor(req);if(!a)return res.status(401).json({message:'Unauthorized'});const s=await seller(req,a),sp=req.scope.resolve('spike') as any;if(!s)return res.status(404).json({message:'Seller not found'});const rows=await sp.listSpikeSettings({key:`seller_profile:${s.id}`},{take:1});const pending=await sp.listSpikeSettings({key:`seller_profile_update:${s.id}`},{take:1});res.json({seller:s,profile:rows[0]?.value||{owner_name:'',store_name:s.name||'',email:s.email||'',phone:'',city:'',address:'',logo_url:''},pending_update:pending[0]?.value||null})}
export async function POST(req:MedusaRequest,res:MedusaResponse){const a=actor(req);if(!a)return res.status(401).json({message:'Unauthorized'});const s=await seller(req,a),sp=req.scope.resolve('spike') as any,b=(req.body||{}) as any;if(!s)return res.status(404).json({message:'Seller not found'});const required=['owner_name','store_name','email','phone','city','address'];for(const f of required){if(!String(b[f]||'').trim())return res.status(422).json({message:`الحقل ${f} مطلوب`,field:f})}const data={owner_name:String(b.owner_name).trim(),store_name:String(b.store_name).trim(),email:String(b.email).trim(),phone:String(b.phone).trim(),city:String(b.city).trim(),address:String(b.address).trim(),governorate:String(b.governorate||'').trim(),logo_url:String(b.logo_url||'').trim(),latitude:b.latitude===''||b.latitude==null?null:Number(b.latitude),longitude:b.longitude===''||b.longitude==null?null:Number(b.longitude),google_maps_url:String(b.google_maps_url||'').trim()};const key=`seller_profile_update:${s.id}`,r=await sp.listSpikeSettings({key},{take:1}),value={status:'pending',data,submitted_at:new Date().toISOString(),reason:null};r.length?await sp.updateSpikeSettings({id:r[0].id,value}):await sp.createSpikeSettings({key,value});await sp.createSpikeNotifications({audience:'admin',seller_id:s.id,type:'store_profile_update',title:'طلب تحديث بيانات متجر',body:`${data.store_name} أرسل تحديثاً لبيانات المتجر`,entity_type:'seller',entity_id:s.id,read:false});res.json({pending_update:value})}
